export function finalizeMatch(s,g,m){if(g.result)return false;if(!m.done)throw Error('Match incomplet');let c=competition(s,g.league),winner=m.score[0]>m.score[1]?g.home:g.away,loser=winner===g.home?g.away:g.home;g.result={score:[...m.score],box:m.box,ot:m.ot,duration:m.duration};
 if(g.stage==='regular'){c.records[winner].wins++;c.records[loser].losses++;[g.home,g.away].forEach((id,i)=>{c.records[id].for+=m.score[i];c.records[id].against+=m.score[1-i]})}
 for(let b of Object.values(m.box)){let p=getPlayer(s,b.id);if(!b.min)continue;p.byLeague[g.league]??=totals();for(let line of [p.season,p.byLeague[g.league]]){line.gp++;for(let k of Object.keys(line))if(k!=='gp')line[k]+=b[k]||0}if(p.returning)p.returning--;p.fatigue=clamp(p.fatigue+b.min*.3);if(rng(s,'career')<CFG.injuryBase*(1+p.fatigue/30)){p.injury=4+Math.floor(rng(s,'career')*15);if(p.id===s.hero)log(s,'Infirmerie',`Indisponibilité de ${p.injury} jours. Reprise progressive ensuite.`)}}
 if(g.home===s.team||g.away===s.team){let p=hero(s),b=m.box[s.hero];s.lastMatch=structuredClone(m);s.grade=m.grade;s.records??={pts:0,reb:0,ast:0,stl:0,blk:0};for(let k of Object.keys(s.records))s.records[k]=Math.max(s.records[k],b?.[k]||0);s.recent.push(m.grade);s.recent=s.recent.slice(-6);s.trust=clamp(s.trust*.75+s.recent.reduce((a,b)=>a+b,0)/s.recent.length*.25);s.relationships.coach=s.trust;
 let competitors=team(s).roster.map(id=>getPlayer(s,id)).filter(q=>q.id!==s.hero&&q.pos===p.pos);let rival=competitors.length?Math.max(...competitors.map(overall)):leagueDef(s.league).level;let expected=14+(overall(p)-rival)*.75+s.trust*.17;s.minutes=Math.round(clamp(expected,8,Math.min(m.duration-5,38)));if(s.career.stage!=='pro')s.minutes=Math.max(18,s.minutes);s.role=s.minutes>=34?'Joueur majeur':s.minutes>=27?'Titulaire':s.minutes>=23?'Sixième homme':s.minutes>=17?'Rotation':'Développement';
 if(b?.min){addXP(s,Math.round(70+b.min*1.8+m.grade*.8));improvePractice(s,b.min);s.career.exposure=clamp(s.career.exposure+.4+(b.pts+b.ast+b.reb)/60);if(s.career.stage!=='pro'&&p.season.gp%5===0)s.career.academics=clamp(s.career.academics-2)}s.form=clamp(s.form*.85+m.grade*.15);log(s,winner===s.team?'Victoire':'Défaite',`${leagueDef(g.league).name} · ${team(s,g.home).name} ${m.score[0]} – ${m.score[1]} ${team(s,g.away).name}. ${b?.pts||0} points, ${b?.ast||0} passes.`)}return true
}
export function simulate(s,g){let m=startMatch(s,g);stepMatch(s,m,20000);finalizeMatch(s,g,m);return m}
function addFixture(s,c,home,away,day,meta={}){let g={id:`s${s.season}-${c.id}-post-${s.nextId++}`,league:c.id,round:100+(c.post?.round||0),home,away,day,result:null,stage:'post',...meta};scheduleDay(s,g,day);c.schedule.push(g);return g}
function winner(g){return g.result.score[0]>g.result.score[1]?g.home:g.away}
function loser(g){return winner(g)===g.home?g.away:g.home}
function orderedBracket(seeds){if(seeds.length===8)return [seeds[0],seeds[7],seeds[3],seeds[4],seeds[1],seeds[6],seeds[2],seeds[5]];if(seeds.length===4)return [seeds[0],seeds[3],seeds[1],seeds[2]];let out=[];for(let i=0;i<seeds.length/2;i++)out.push(seeds[i],seeds[seeds.length-1-i]);return out}
function beginSeries(s,c,seeds,day){let best=leagueDef(c.id).series[c.post.round]||1;c.post.stage='series';c.post.series=[];for(let i=0;i<seeds.length;i+=2){let pair={a:seeds[i],b:seeds[i+1],wins:[0,0],games:[],best,winner:null};let g=addFixture(s,c,pair.a,pair.b,day,{series:i/2});pair.games.push(g.id);c.post.series.push(pair)}}
function startPostseason(s,c){let def=leagueDef(c.id),rank=standings(s,c.id),day=Math.max(...c.schedule.map(g=>g.day))+3;c.phase='Playoffs';c.post={stage:'',round:0,groups:[]};let pools=def.id==='nba'?['Est','Ouest'].map(conf=>rank.filter(t=>t.conference===conf)): [rank];
 if(def.playIn){c.phase='Play-in';c.post.stage='playin';for(let pool of pools){let direct=def.id==='nbl'?2:6;let group={locked:pool.slice(0,direct).map(t=>t.id),a:null,b:null,last:null,seeds:null};group.a=addFixture(s,c,pool[direct].id,pool[direct+1].id,day,{stage:'playin'}).id;group.b=addFixture(s,c,pool[direct+2].id,pool[direct+3].id,day,{stage:'playin'}).id;c.post.groups.push(group)}}else beginSeries(s,c,orderedBracket(rank.slice(0,def.playoff).map(t=>t.id)),day)
}
function updateCompetition(s,c){if(c.phase==='Terminée')return;if(!c.post){if(c.schedule.every(g=>g.result))startPostseason(s,c);return}if(c.post.stage==='playin'){for(let group of c.post.groups){let a=c.schedule.find(g=>g.id===group.a),b=c.schedule.find(g=>g.id===group.b);if(a.result&&b.result&&!group.last)group.last=addFixture(s,c,loser(a),winner(b),Math.max(a.day,b.day)+3,{stage:'playin'}).id;let last=c.schedule.find(g=>g.id===group.last);if(last?.result)group.seeds=[...group.locked,winner(a),winner(last)]}if(c.post.groups.every(g=>g.seeds)){let seeds=c.post.groups.flatMap(g=>orderedBracket(g.seeds));c.phase='Playoffs';beginSeries(s,c,seeds,Math.max(...c.schedule.map(g=>g.day))+3)}return}
 for(let pair of c.post.series){if(pair.winner)continue;let games=pair.games.map(id=>c.schedule.find(g=>g.id===id));let last=games.at(-1);if(!last.result)continue;pair.wins=[games.filter(g=>g.result&&winner(g)===pair.a).length,games.filter(g=>g.result&&winner(g)===pair.b).length];let target=Math.ceil(pair.best/2);if(Math.max(...pair.wins)>=target){pair.winner=pair.wins[0]>=target?pair.a:pair.b;continue}let n=games.length;let home=n%4<2?pair.a:pair.b;let g=addFixture(s,c,home,home===pair.a?pair.b:pair.a,last.day+2,{series:c.post.series.indexOf(pair)});pair.games.push(g.id)}
 if(c.post.series.every(p=>p.winner)){let winners=c.post.series.map(p=>p.winner);if(winners.length===1){c.champion=winners[0];c.phase='Terminée';log(s,'Champion',`${team(s,c.champion).name} remporte ${leagueDef(c.id).name}.`)}else{c.post.round++;beginSeries(s,c,winners,Math.max(...c.schedule.map(g=>g.day))+3)}}
}
export function continueMatch(s,strategy,count){if(!s.match)return;let m=s.match;m.strategy=strategy||m.strategy;stepMatch(s,m,count);if(m.done){let c=competition(s,m.league),g=c.schedule.find(g=>g.id===m.id);finalizeMatch(s,g,m);s.match=null;updateCompetition(s,c);syncLeague(s)}}
export function next(s,{interactive=true,untilDay=null}={}){if(s.retired||s.pending||s.match)return false;syncLeague(s);for(let c of s.competitions)updateCompetition(s,c);let games=allGames(s).filter(g=>!g.result).sort((a,b)=>a.day-b.day||a.id.localeCompare(b.id));if(!games.length){finishYear(s);return true}let mine=games.find(g=>g.home===s.team||g.away===s.team);let target=mine?.day??games[0].day;let boundary=Math.min(...s.competitions.filter(c=>!c.post).map(c=>Math.max(...c.schedule.map(g=>g.day))),Infinity);target=Math.min(target,boundary);if(untilDay!==null)target=Math.min(target,untilDay);target=Math.max(s.day,target);let work=!!mine&&mine.day<=target;advanceDay(s,target,work||untilDay!==null);
 let due=games.filter(g=>g.day<=target);for(let g of due.filter(g=>g.home!==s.team&&g.away!==s.team)){simulate(s,g);updateCompetition(s,competition(s,g.league))}for(let g of due.filter(g=>g.home===s.team||g.away===s.team)){if(interactive&&s.mode!=='quick'){s.match=startMatch(s,g);syncLeague(s);return true}simulate(s,g);updateCompetition(s,competition(s,g.league))}syncLeague(s);return true
}

export function scouting(s){let p=hero(s),st=p.season,production=st.min?(st.pts+st.ast*1.5+st.reb)*30/st.min:0,potential=KEYS.reduce((n,k)=>n+p.caps[k],0)/KEYS.length;let score=overall(p)*.72+potential*.16+Math.min(28,production)*.24+(22-p.age)*.65+(s.career.exposure-50)*.025-(p.injury?4:0);return {score:+score.toFixed(1),production:+production.toFixed(1),projection:score>=79?'Top 10':score>=73?'Premier tour':score>=68?'Second tour':score>=64?'Fin de draft / non-drafté':'Non-drafté probable'}}
function offerFor(s,t,{academic=false,draftRank=null}={}){let p=hero(s),def=leagueDef(t.league),score=overall(p),rivals=t.roster.map(id=>getPlayer(s,id)).filter(q=>q.pos===p.pos&&q.id!==s.hero),rival=rivals.length?Math.max(...rivals.map(overall)):def.level;let payroll=t.roster.filter(id=>id!==s.hero).map(id=>getPlayer(s,id)).sort((a,b)=>overall(b)-overall(a)).slice(0,9).reduce((n,q)=>n+q.contract.salary,0);let salary=academic?0:Math.min(Math.max(def.salary,def.salary*(1+(score-def.minOffer)/8)),Math.max(def.salary,t.budget-payroll));return {id:`offer-${s.nextId++}`,team:t.id,league:t.league,years:academic?1:draftRank?2:2+(score>78?1:0),salary:Math.round(salary),guarantee:1,option:draftRank?'Équipe':'Aucune',role:score>=rival?'Titulaire':score>=rival-8?'Rotation':'Développement',minutes:Math.round(clamp(24+(score-rival)*.7,12,34)),expires:s.day+14,academic,draftRank,reason:academic?`Programme ${rival>=65?'sélectif':'accessible'} · concurrence ${rival} · résultats scolaires ${Math.round(s.career.academics)}/100`:`${def.name} · niveau ${score} face à une concurrence de ${rival} au poste`}}
export function marketOffers(s,{includeNBA=true}={}){let p=hero(s),rating=overall(p)+(s.grade-50)/20+Math.min(3,s.career.exposure/30),offers=[];for(let def of LEAGUES.filter(l=>!l.amateur)){if(def.id==='nba'&&!includeNBA)continue;let clubs=s.teams.filter(t=>t.league===def.id&&t.id!==s.team&&rating>=def.minOffer&&(!t.competitions.includes('euroleague')||rating>=67));clubs.sort((a,b)=>{let fit=t=>t.roster.filter(id=>getPlayer(s,id).pos===p.pos).reduce((n,id)=>Math.max(n,overall(getPlayer(s,id))),45);return fit(a)-fit(b)});if(clubs.length)offers.push(offerFor(s,clubs[0]));}if(!offers.length){let club=s.teams.filter(t=>t.league==='elite'&&!t.competitions.includes('euroleague')).sort((a,b)=>a.roster.reduce((n,id)=>n+overall(getPlayer(s,id)),0)-b.roster.reduce((n,id)=>n+overall(getPlayer(s,id)),0))[0];let o=offerFor(s,club);o.role='Développement';o.minutes=8;o.salary=45000;o.reason='Contrat de développement : faible salaire, temps de jeu à gagner.';offers.push(o)}return offers}
function collegeOffers(s){let score=(s.lastSeasonScouting||scouting(s)).score,clubs=s.teams.filter(t=>t.league==='ncaa');let ranked=clubs.sort((a,b)=>b.roster.reduce((n,id)=>n+overall(getPlayer(s,id)),0)-a.roster.reduce((n,id)=>n+overall(getPlayer(s,id)),0));let start=score>=67&&s.career.academics>=65?0:score>=60?9:23;return ranked.slice(start,start+3).map(t=>offerFor(s,t,{academic:true}))}
function moveHero(s,destination){let old=team(s),dest=team(s,destination),p=hero(s);if(old.id===dest.id)return;old.roster=old.roster.filter(id=>id!==s.hero);let replacement=generatedPlayer(s,`replacement-${s.season}-${s.nextId++}`,old);s.players.push(replacement);old.roster.push(replacement.id);let weakest=dest.roster.map(id=>getPlayer(s,id)).sort((a,b)=>overall(a)-overall(b))[0];dest.roster=dest.roster.filter(id=>id!==weakest.id);s.freeAgents.push(weakest.id);dest.roster.push(s.hero);s.team=dest.id;s.league=dest.league;s.system=clamp(s.system*.55);s.trust=50;s.recent=[];p.fatigue=clamp(p.fatigue-15)}
export function sign(s,index){let o=s.offers[index];if(!o||s.pending?.type!=='contract')return false;let origin=team(s).name;moveHero(s,o.team);let p=hero(s);p.contract={years:o.years,salary:o.salary,guarantee:o.guarantee,option:o.option};s.role=o.role;s.minutes=o.minutes;if(o.academic){s.career.stage='college';s.career.collegeYears=0}else s.career.stage='pro';s.pending=null;s.offers=[];s.lastTransfer=s.day;s.career.milestones.push({season:s.season,day:s.day,text:`${origin} → ${team(s).name} (${leagueDef(s.league).name})`});log(s,o.academic?'Université choisie':'Contrat signé',`${team(s).name} · ${leagueDef(s.league).name} · ${o.academic?'Scolarité et basket universitaire':`${o.years} ans · ${o.salary.toLocaleString('fr-FR')} € par saison (simulation)`} · rôle ${o.role}.`);syncLeague(s);return true}
export function requestTrade(s){if(s.pending||s.match||s.retired)return false;if(s.career.stage!=='pro'){log(s,'Orientation','Terminez votre saison : les choix universitaires et professionnels arrivent à l’intersaison.');return false}if(s.lastMarketDay!==undefined&&s.day-s.lastMarketDay<20){log(s,'Agent','Les clubs attendent de nouvelles performances. Prochaine démarche après vingt jours.');return false}s.lastMarketDay=s.day;if(hero(s).contract.years>1&&s.round<8){log(s,'Transfert refusé','Votre club ne vous libère pas aussi tôt. Huit matchs et de nouvelles performances sont nécessaires avant une autre démarche.');s.relationships.agent=clamp(s.relationships.agent+3);return false}s.offers=marketOffers(s);s.pending={type:'contract',title:'Votre marché international',text:'Offres filtrées selon votre niveau, votre production et les besoins des clubs. Le changement de pays conserve votre carrière ; vous rejoignez le calendrier en cours.',canDecline:true};return true}
export function enterDraft(s){if(s.career.draftEntered||s.career.stage!=='college'||hero(s).age<19||s.career.collegeYears<1)return false;let estimate=s.lastSeasonScouting||scouting(s);let prospects=Array.from({length:100},(_,i)=>({id:'prospect-'+i,score:55+rng(s,'players')*29+(i<8?4:0)}));let actual=estimate.score+(rng(s,'career')-.5)*4;let rank=1+prospects.filter(p=>p.score>actual).length;s.career.draftEntered=true;s.draftResult={season:s.season-1,rank:rank<=60?rank:null,projection:estimate.projection,evaluation:actual};
 let prior=s.archives.at(-1)?.competitions?.find(c=>c.id==='nba')?.records;let nba=prior?Object.entries(prior).sort((a,b)=>a[1].wins-b[1].wins||(a[1].for-a[1].against)-(b[1].for-b[1].against)).map(([id])=>team(s,id)):standings(s,'nba').reverse();if(rank<=60){let t=nba[(rank-1)%30];s.offers=[offerFor(s,t,{draftRank:rank}),...marketOffers(s,{includeNBA:false}).slice(0,3)];s.pending={type:'contract',title:`Draft NBA · choix n° ${rank}`,text:`${t.name} vous sélectionne. Vous pouvez signer dans cette franchise ou choisir une offre hors NBA. Aucune autre franchise NBA ne vous est proposée à la draft.`};log(s,'Draft NBA',`${hero(s).name} sélectionné n° ${rank} par ${t.name}.`)}else{s.offers=marketOffers(s,{includeNBA:false});s.pending={type:'contract',title:'Non-drafté : votre carrière continue',text:'Aucune franchise ne vous a sélectionné. Voici les possibilités concrètes à l’étranger. De bonnes performances pourront ouvrir une porte en NBA lors d’un prochain marché.'};log(s,'Draft NBA','Non-drafté. Votre agent recherche des clubs dans les championnats compatibles avec votre niveau.')}return true}
export function decide(s,choice){if(!s.pending)return false;if(choice==='decline'&&s.pending.canDecline){s.pending=null;s.offers=[];syncLeague(s);return true}if(s.pending.type==='draft-choice'){if(choice==='stay'&&s.career.collegeYears<4){s.pending=null;syncLeague(s);log(s,'Retour à l’université',`Année ${s.career.collegeYears+1} avec ${team(s).name}. Votre progression et votre exposition se poursuivent.`);return true}if(choice==='draft')return enterDraft(s)}return false}
function refreshAI(s){for(let t of s.teams){let def=leagueDef(t.league);for(let id of [...t.roster]){if(id===s.hero)continue;let p=getPlayer(s,id);p.age++;p.contract.years--;let depart=def.amateur?p.age>(def.id==='highschool'?18:22):p.age>=38||p.contract.years<=0&&overall(p)<def.level-2;if(depart){let q=generatedPlayer(s,`new-${s.season}-${s.nextId++}`,t,def.amateur?(def.id==='highschool'?16:18):19);s.players.push(q);t.roster=t.roster.map(x=>x===id?q.id:x);if(!def.amateur)s.lastDraft.push({name:q.name,team:t.name,league:t.league,pos:q.pos,ovr:overall(q),age:q.age})}else{for(let k of KEYS)p.attrs[k]=clamp(p.attrs[k]+(p.age<25?1:p.age>31?-1:0),25,94);if(p.contract.years<=0)p.contract.years=2;p.season=totals();p.byLeague={};p.fatigue=0;p.injury=0}}}s.players=s.players.filter(p=>p.id===s.hero||s.teams.some(t=>t.roster.includes(p.id)));s.freeAgents=[]}
function finishYear(s){let p=hero(s),stage=s.career.stage,oldYear=s.season;advanceDay(s,s.season*365,false);let primary=competition(s);let leaders=s.players.filter(q=>q.byLeague[s.league]?.gp>5).sort((a,b)=>{let value=q=>{let t=q.byLeague[s.league];return(t.pts+t.ast*1.5+t.reb)/t.gp};return value(b)-value(a)});s.history.push({season:s.season,team:team(s).name,league:s.league,stage,stats:structuredClone(p.season),ovr:overall(p),champion:primary.champion?team(s,primary.champion).name:'—',mvp:leaders[0]?.name||'—',salary:p.contract.salary});s.archives.push({season:s.season,team:s.team,league:s.league,competitions:s.competitions.map(c=>({id:c.id,champion:c.champion,records:structuredClone(c.records),games:c.schedule.map(g=>({id:g.id,home:g.home,away:g.away,round:g.round,league:g.league,day:g.day,stage:g.stage,score:g.result?.score||null}))}))});
 for(let c of s.competitions)if(c.champion===s.team)s.trophies.push(`${leagueDef(c.id).name} · champion saison ${s.season}`);if(leaders[0]?.id===s.hero)s.trophies.push(`MVP ${leagueDef(s.league).name} · saison ${s.season}`);s.lastSeasonScouting=scouting(s);s.lastSeasonStats=structuredClone(p.season);p.age++;if(stage==='highschool')s.career.hsYears++;if(stage==='college')s.career.collegeYears++;if(stage==='pro'){if(p.contract.years===1&&p.contract.option==='Équipe'&&overall(p)>=72){p.contract.years++;p.contract.option='Aucune';log(s,'Option exercée','Votre club prolonge votre contrat d’une saison.')}p.contract.years=Math.max(0,p.contract.years-1)}
 s.season++;s.lastDraft=[];refreshAI(s);p.season=totals();p.byLeague={};p.fatigue=0;p.injury=0;for(let k of KEYS)if(p.age>32)p.attrs[k]=Math.max(25,p.attrs[k]-1);setupCompetitions(s);s.lastMatch=null;log(s,'Nouvelle saison',`Saison ${s.season}. ${p.age} ans · ${overall(p)} de général · ${s.development.gained} améliorations depuis le début.`);
 if(p.age>=40){s.retired=true;log(s,'Retraite','Votre carrière se termine. Les archives, contrats et statistiques restent consultables.')}else if(stage==='highschool'&&p.age>=18){s.offers=collegeOffers(s);s.pending={type:'contract',title:'Du lycée à l’université',text:`Deux éléments comptent : le basket et les études. Votre dossier (${Math.round(s.career.academics)}/100) et vos performances ont retenu l’attention de ces programmes.`}}else if(stage==='college'){s.pending={type:'draft-choice',title:s.career.collegeYears>=4?'Dernière année universitaire terminée':'Rester à l’université ou tenter la NBA ?',text:`${s.career.collegeYears} saison(s) universitaire(s). Projection : ${s.lastSeasonScouting.projection}. ${s.career.collegeYears<4?'Une autre saison peut améliorer votre niveau et votre position.':'Votre éligibilité universitaire est épuisée : place au passage professionnel.'}`}}else if(stage==='pro'&&p.contract.years===0){s.offers=marketOffers(s);s.offers.unshift(offerFor(s,team(s)));s.pending={type:'contract',title:'Fin de contrat · quel championnat ensuite ?',text:'Restez dans votre club ou changez de ligue selon les propositions obtenues.'}}
 syncLeague(s)
}
export function grade(n){return n>=90?'A+':n>=80?'A':n>=70?'B+':n>=60?'B':n>=50?'C':n>=40?'D':'F'}
export function migrateLegacy(old){if(!old||![1,2].includes(old.schema)||!Array.isArray(old.players)||!Array.isArray(old.teams))throw Error('Ancienne sauvegarde invalide');let p=old.players.find(p=>p.id===old.hero);if(!p?.attrs||KEYS.some(k=>!Number.isFinite(p.attrs[k])||p.attrs[k]<25||p.attrs[k]>99))throw Error('Ancien joueur invalide');let build={...defaultBuild(),...p,path:old.phase==='Formation'?(p.age<18?'young':'prospect'):'rookie',seed:old.rng.players,caps:p.caps};let s=createGame(build),q=hero(s);for(let key of ['name','age','attrs','caps','absolute','badges','learned','equipped','height','weight','wingspan','pos','secondary','nation','style'])q[key]=structuredClone(p[key]);q.practice={};s.points=old.points;s.xp=old.xp;s.auto=old.auto??true;s.money=old.money;s.history=structuredClone(old.history||[]);s.trophies=structuredClone(old.trophies||[]);s.records=structuredClone(old.records||{});s.legacyArchive={season:old.season,team:old.teams.find(t=>t.id===old.team)?.name,stats:p.season,calendar:old.schedule,match:old.match,log:old.log};s.season=old.season+1;s.day=(s.season-1)*365;setupCompetitions(s);s.pending=null;if(s.career.stage==='pro'){s.offers=marketOffers(s);s.pending={type:'contract',title:'Votre carrière rejoint les ligues réelles',text:'Votre joueur, ses attributs, points, revenus et historique ont été conservés. L’ancienne saison est archivée ; choisissez une offre pour commencer dans le nouveau championnat.'}}log(s,'Mise à jour 2.0','Progression accélérée, monde multi-ligues et nouveau parcours scolaire. Une copie intégrale de l’ancienne sauvegarde est conservée séparément.');return syncLeague(s)}
export function validate(s){if(!s||s.schema!==3||s.engine!==VERSION||!Array.isArray(s.players)||!Array.isArray(s.teams)||!Array.isArray(s.competitions)||s.competitions.length!==LEAGUES.length||!s.career||!s.rng)throw Error('Sauvegarde incompatible');let ids=new Set();for(let p of s.players){if(typeof p.id!=='string'||!/^[a-zA-Z0-9-]{1,150}$/.test(p.id)||ids.has(p.id))throw Error('Identifiant joueur invalide');ids.add(p.id);if(!WEIGHTS[p.pos]||typeof p.name!=='string'||!Number.isFinite(p.age)||p.age<16||p.age>80||KEYS.some(k=>!Number.isFinite(p.attrs?.[k])||p.attrs[k]<25||p.attrs[k]>99)||!p.season||!p.byLeague||!p.contract||!p.badges||!Array.isArray(p.equipped)||!Array.isArray(p.learned))throw Error('Joueur invalide')}
 let active=new Set(),clubs=new Set();for(let t of s.teams){if(clubs.has(t.id)||!leagueDef(t.league)||typeof t.name!=='string'||t.roster?.length!==10)throw Error('Club invalide');clubs.add(t.id);for(let id of t.roster){if(!ids.has(id)||active.has(id))throw Error('Effectif incohérent');active.add(id)}}let p=hero(s);if(!p||!active.has(s.hero)||!clubs.has(s.team)||!leagueDef(s.league)||!STYLES[p.style]||KEYS.some(k=>!Number.isFinite(p.caps?.[k])||p.attrs[k]>p.caps[k]||p.caps[k]>p.absolute[k])||potentialCost(p.caps)>CFG.budget+.01)throw Error('Profil invalide');for(let k of ['day','season','points','xp','money','trust','minutes','grade','nextId'])if(!Number.isFinite(s[k])||s[k]<0)throw Error('Progression invalide');for(let key of ['match','players','career'])if(!Number.isInteger(s.rng[key])||s.rng[key]<=0||s.rng[key]>4294967295)throw Error('Aléatoire invalide');if(!team(s).roster.includes(s.hero)||!team(s).competitions.includes(s.league)||!['highschool','college','pro'].includes(s.career.stage)||!KEYS.includes(s.training)||!['quick','key','detail'].includes(s.mode))throw Error('Carrière invalide');for(let o of s.offers||[])if(!clubs.has(o.team)||!Number.isFinite(o.salary)||o.salary<0||!Number.isInteger(o.years)||o.years<1||!Number.isFinite(o.minutes)||o.minutes<0||o.minutes>48)throw Error('Offre invalide');let gids=new Set(),cids=new Set();for(let c of s.competitions){if(cids.has(c.id))throw Error('Compétition dupliquée');cids.add(c.id);if(!leagueDef(c.id)||!Array.isArray(c.schedule)||!c.records)throw Error('Compétition invalide');for(let g of c.schedule){if(gids.has(g.id)||g.league!==c.id||!clubs.has(g.home)||!clubs.has(g.away)||g.home===g.away||!Number.isFinite(g.day))throw Error('Calendrier invalide');gids.add(g.id);if(g.result&&(!Array.isArray(g.result.score)||g.result.score.length!==2||g.result.score.some(x=>!Number.isInteger(x)||x<0)))throw Error('Résultat invalide')}}if(s.match&&(!gids.has(s.match.id)||!s.match.box||!Number.isInteger(s.match.n)))throw Error('Match invalide');for(let k of ['log','history','archives','offers','trophies','recent'])if(!Array.isArray(s[k]))throw Error('Historique invalide');if(s.pending&&!['contract','draft-choice'].includes(s.pending.type))throw Error('Décision invalide');return syncLeague(s)}
